<script setup lang="ts">
import { ref, watch } from 'vue';
import { evidenceStateLabel, type EvidenceRow } from '../lib/repairEvidence';
const props = defineProps<{ row: EvidenceRow; base: string; expanded: boolean; wide?: boolean }>();
defineEmits<{ locate: []; toggle: [] }>();
const broken = ref<Record<string, boolean>>({});
watch(() => [props.row.row_id, props.row.evidence_state, props.base], () => { broken.value = {}; });
function source(role: string) { return `${props.base}/rows/${props.row.row_id}/assets/${props.row.manifest.windows?.[0]?.window_id}/${role}`; }
function available(role: string) { return props.row.evidence_state === 'ready' && props.row.manifest.windows?.[0]?.assets.some(a => a.role === role) && !broken.value[role]; }
</script>
<template>
<article class="evidence-row" :class="{'wide-row':wide}">
<div class="region"><strong :title="row.region_id">{{ row.region_id }}</strong><span :title="row.plan.scene_name || row.item_id">{{ row.plan.scene_name || row.item_id }}</span></div>
<div class="pair"><figure v-for="role in ['nosr','output']" :key="role"><a v-if="available(role)" :href="source(role)" target="_blank" rel="noopener"><img :src="source(role)" :alt="role === 'nosr' ? 'NOSR' : '修复产物'" loading="lazy" @error="broken[role] = true"></a><div v-else class="missing">{{ row.evidence_state === 'ready' ? '证据缺失' : evidenceStateLabel(row.evidence_state) }}</div><figcaption>{{ role === 'nosr' ? 'NOSR' : '修复产物' }}</figcaption></figure></div>
<div class="observation"><div class="meta"><span :title="`${row.plan.scene_name || row.item_id} · ${row.region_id}`">{{ row.plan.scene_name || row.item_id }} · {{ row.region_id }}</span><small>{{ row.analysis_state === 'ready' ? '已分析' : evidenceStateLabel(row.analysis_state) }}</small></div><h3 :title="row.analysis?.observation">{{ row.analysis?.observation || '暂未分析' }}</h3><p :title="row.analysis?.recommendation">{{ row.analysis?.recommendation || (row.evidence_state !== 'ready' ? evidenceStateLabel(row.evidence_state) : '等待分析意见，可定位人工复核') }}</p><small v-if="row.analysis && row.analysis_state !== 'ready'">保留最近成功意见</small><div class="compact-actions"><button @click="$emit('locate')">定位复核</button><button :aria-expanded="expanded" @click="$emit('toggle')">{{ expanded ? '收起详情' : '展开详情' }}</button></div></div>
<div class="operations"><button class="primary" @click="$emit('locate')">定位复核</button><button :aria-expanded="expanded" @click="$emit('toggle')">{{ expanded ? '收起详情' : '展开详情' }}</button></div>
</article>
</template>
<style scoped>
.evidence-row{display:grid;grid-template-columns:112px minmax(0,1fr);gap:10px;padding:12px;border-bottom:1px solid #e3ebe5;align-items:center;min-width:0;background:#fff}.region{display:none;min-width:0}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px;min-width:0}figure{position:relative;margin:0;aspect-ratio:1;border:1px solid #d4dfd5;border-radius:6px;overflow:hidden;background:#f2f5f1}figure a{display:block;width:100%;height:100%}img{display:block;width:100%;height:100%;object-fit:contain}figcaption{position:absolute;bottom:0;left:0;padding:1px 3px;font-size:8px;font-weight:700;color:#315e48;background:#f8fbf4e8;pointer-events:none}.missing{display:grid;place-items:center;height:100%;font-size:10px;color:#7f9589;text-align:center}.observation{min-width:0}.meta{display:flex;gap:5px;justify-content:space-between;color:#879b8e;font-size:10px}.meta span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.meta small{flex-shrink:0;font-size:10px}h3{font-size:13px;line-height:1.5;margin:4px 0 2px;color:#29483c;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}p{margin:0;color:#839789;font-size:11px;display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}button{font:inherit;cursor:pointer;border:0;background:transparent;color:#357358;padding:4px 0;text-align:left;font-size:11px}.compact-actions{display:flex;gap:10px}.compact-actions button:first-child{font-weight:650}.operations{display:none}.wide-row{grid-template-columns:100px minmax(180px,30%) minmax(0,1fr) 110px;gap:20px;padding:16px 24px;align-items:start}.wide-row .region{display:flex;flex-direction:column;gap:6px;overflow:hidden}.wide-row .region strong{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wide-row .region span{font-size:12px;color:#879b8e;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wide-row .operations{display:flex;flex-direction:column;gap:10px;align-items:center}.wide-row .primary{background:#183f3b;color:white;font-weight:600;padding:12px 20px;border-radius:9px;white-space:nowrap}.wide-row .compact-actions{display:none}.wide-row h3{font-size:16px;margin-top:4px}.wide-row p{font-size:13px;-webkit-line-clamp:2;margin-top:6px}.wide-row figure{max-height:130px}.wide-row figcaption{font-size:11px;padding:3px 6px}@media(max-width:1000px){.wide-row{grid-template-columns:112px minmax(0,1fr);padding:12px;gap:10px}.wide-row .region,.wide-row .operations{display:none}.wide-row .compact-actions{display:flex}}
</style>
